export default class FormatValue{constructor(){this.formatValueAdd=this.formatValueAdd.bind(this),this.formatValueList=this.formatValueList.bind(this),this.formatValueSearch=this.formatValueSearch.bind(this),this.removeFormat=this.removeFormat.bind(this)}formatValueAdd(e){let t=e.target,r=t.value.replace(/[^\d]/g,"");r=(r/100).toFixed(2),r=parseFloat(r).toLocaleString("pt-BR",{style:"currency",currency:"BRL"}),t.value=r}formatValueList(e){return"string"==typeof e&&(e=parseFloat(e.replace(/[^\d.-]/g,""))),e=parseFloat(e).toLocaleString("pt-BR",{style:"currency",currency:"BRL"})}formatValueSearch(e){let t=e.target,r=t.value.replace(/[^\d]/g,"");r=(r/100).toFixed(2),t.value=parseFloat(r).toLocaleString("pt-BR",{style:"currency",currency:"BRL"})}removeFormat(e){return e.replace(/[R$\s.]/g,"").replace(",",".")}}